body:
This

    #!/usr/bin/perl

    sub PVBM () { 'foo' }
    index "foo", PVBM;

    $x = PVBM;

    my $str = 'foo';
    my $pvlv = \\substr $str, 0, 1;

    $x = $pvlv;

    __END__

causes (the same) assertion failure in glob_assign_ref, which it should
never have got to in the first place. The patch below appears to fix it.

Ben

diff -ur perl-current/sv.c perl-current-pvbm/sv.c
--- perl-current/sv.c	Sat Oct  6 22:32:11 2007
+++ perl-current-pvbm/sv.c	Tue Oct 16 18:20:31 2007
@@ -3536,7 +3536,7 @@
 	}

 	if (dtype >= SVt_PV) {
-	    if (dtype == SVt_PVGV) {
+	    if (dtype == SVt_PVGV && isGV_with_GP(dstr)) {
 		glob_assign_ref(dstr, sstr);
 		return;
 	    }
diff -ur perl-current/t/op/lex_assign.t perl-current-pvbm/t/op/lex_assign.t
--- perl-current/t/op/lex_assign.t	Tue Jun 13 20:29:32 2006
+++ perl-current-pvbm/t/op/lex_assign.t	Tue Oct 16 18:41:09 2007
@@ -24,7 +24,7 @@

 @INPUT = ;
 @simple_input = grep /^\\s*\\w+\\s*\\$\\w+\\s*[#\\n]/, @INPUT;
-print "1..", (10 + @INPUT + @simple_input), "\\n";
+print "1..", (11 + @INPUT + @simple_input), "\\n";
 $ord = 0;

 sub wrn {"@_"}
@@ -170,6 +170,25 @@
     }
   }
 }
+
+$ord++;
+eval {
+    sub PVBM () { 'foo' }
+    index 'foo', PVBM;
+    my $x = PVBM;
+
+    my $str = 'foo';
+    my $pvlv = \\substr $str, 0, 1;
+    $x = $pvlv;
+
+    1;
+};
+if ($@) {
+    warn "# $@";
+    print 'not ';
+}
+print "ok $ord\\n";
+
 __END__
 ref $xref			# ref
 ref $cstr			# ref nonref

